def capture(source_paths, request, domain='A'):
    result = {'stage': ACTIONS.get(request.get('action'), 'A_fixed_rpc') if domain == 'A' else 'PC_fixed_rpc', 'source_reason_code': 'owned_A_RPC_failed_no_retry' if domain == 'A' else 'owned_PC_RPC_failed_no_retry', 'error_type': 'FixedFailure'}

    def trace(frame, event, arg):
        if event == 'exception' and (frame.f_code.co_filename in source_paths or frame.f_code.co_filename == '<fixed_protected_RPC_bootstrap>'):
            kind, error, tb = arg
            plan = frame.f_globals.get('plan')
            if plan is not None and getattr(plan, '__file__', None) in source_paths and (kind is getattr(plan, 'Refused', None)):
                value = str(error)
                if value in (VOCAB if domain == 'A' else PC_VOCAB):
                    result.update(source_reason_code=value, error_type='Refused')
            elif kind is RuntimeError and frame.f_code.co_filename == '<fixed_protected_RPC_bootstrap>' and (str(error) in BOOTSTRAP_VOCAB):
                result.update(source_reason_code=str(error), error_type='ProtectedSource')
        return trace
    return (trace, result)
